  gem_ruby:     { canDipTarget: canGemSocketDipTarget, onDip: createGemSocketDipHook("gem_ruby") },
  gem_sapphire: { canDipTarget: canGemSocketDipTarget, onDip: createGemSocketDipHook("gem_sapphire") },
