  potion: { route: 'oral', doses: 1, channels: [], effects: [{ key: 'poison', duration: 10, turnsLeft: 10, potency: 2, stack: 'add', maxStacks: 3 }], toxicity: null, feel: 'It tastes acrid and vile. Your stomach heaves!' },
