    on_drink: (ctx, state) => {
      const actorId = Number(state?.actor || ctx.actor || 0) | 0;
      const targetId = ctx.rules.resolveTarget(actorId);
      const turns = ctx.helpers.int(30, 40);
      const potency = ctx.helpers.int(2, 3);
