/**
 * @param {any} ctx
 * @param {{ damageDice?: string }} info
 * @param {number} actor
 */
function rollThrowImpactDamage(ctx, info, actor) {
  const dice = String(info?.damageDice || "1d2");
  const base = Math.max(1, Number(ctx.fx.roll(dice) || 0) | 0);
  const snapshot = ctx.query.combatSnapshot(actor, "ranged");
  const flat = Math.max(0, Number(snapshot?.damageFlatBonus || 0) | 0);
  return Math.max(1, base + flat);
}

/**
 * Canonical throw interaction pipeline.
 *
 * Behavior:
 * - runs throw hooks from item defs (`beforeThrow` / `onThrow` / `afterThrow`)
 * - if hooks do not consume the item, applies default throw behavior:
 *   remove from inventory and place on the landing tile
 * - supports hook opt-out via `{ skipBaseThrow: true }`
 *
 * @param {any} ctx
 */
export function throwPipeline(ctx) {
  const actor = ctx.actor | 0;
  const itemId = ctx.primary | 0;
  const targetId = ctx.target | 0;
  const intent = (ctx.params?.intent && typeof ctx.params.intent === "object")
    ? ctx.params.intent
    : null;

  const metrics = {
    consumed: false,
    dropped: false,
    impacted: false,
    impactDamage: 0,
    payloadMatched: false,
    path: "none",
    range: 0,
    maxRange: 0,
    weight: 0,
  };

  if (!(actor > 0) || !(itemId > 0)) {
    ctx.cancel({ code: "THROW_GATE_INVALID", message: "Missing actor or item for throw action." });
    return { metrics };
  }
  if (!ctx.query.alive(actor)) {
    ctx.cancel({ code: "THROW_GATE_NO_ACTOR", message: "Actor is not alive." });
    return { metrics };
  }
  if (!ctx.query.alive(itemId)) {
    ctx.cancel({ code: "THROW_GATE_NO_ITEM", message: "Item no longer exists." });
    return { metrics };
  }
  if (!ctx.rules.hasItemInInventory(actor, itemId)) {
    ctx.cancel({ code: "THROW_GATE_NOT_OWNED", message: "Item is not in inventory." });
    return { metrics };
  }

  const actorPos = ctx.query.get(actor, Position);
  if (!actorPos) {
    ctx.cancel({ code: "THROW_GATE_NO_POSITION", message: "Actor position is required to throw." });
    return { metrics };
  }

  const info = ctx.query.itemInfo(itemId);
  const identity = String(ctx.query.identity(itemId) || "").toLowerCase();
  const rawWeight = Number(info?.weight);
  const weight = Number.isFinite(rawWeight) && rawWeight > 0 ? rawWeight : 1;
  const throwSpec = normalizeThrowSpec(ctx.params?.throwSpec, actorPos, weight);
  metrics.range = throwSpec.range;
  metrics.maxRange = throwSpec.maxRange;
  metrics.weight = throwSpec.weight;

  const state = {
    actor,
    itemId,
    targetId,
    identity,
    info,
    intent,
    throw: throwSpec,
    targetX: throwSpec.to.x,
    targetY: throwSpec.to.y,
    weight: throwSpec.weight,
  };

  const payload = findThrowPayload(state);
  if (payload) {
    metrics.payloadMatched = true;
    metrics.path = String(payload.source || "payload");
  }

  const hookOut = payload ? runThrowHooks(ctx, payload, state) : {};
  let scriptOut;
  if (!ctx.cancelled) {
    const scriptRef = ctx.query.get(itemId, ScriptRef);
    if (scriptRef) {
      scriptOut = ctx.rules.runScript(scriptRef, ScriptVerb.ItemThrow, {
        ...state,
        targetId,
        targetX: throwSpec.to.x,
        targetY: throwSpec.to.y,
        interaction: ctx,
      });
    }
  }
  if (ctx.cancelled) {
    return {
      metrics,
      payload: {
        defId: payload ? String(payload.id || "") : null,
        path: payload ? String(payload.source || "payload") : "none",
        hooks: hookOut,
        script: scriptOut,
        throw: throwSpec,
      },
    };
  }

  const hookResult = normalizeThrowHookResult(
    hookOut.onThrow !== undefined ? hookOut.onThrow : scriptOut,
  );
  if (hookResult.cancelled) {
    ctx.cancel({
      code: String(hookResult.code || "THROW_CANCELLED"),
      message: String(hookResult.message || "Throw action cancelled."),
      consumesTurn: hookResult.consumesTurn === true,
      detail: hookResult.detail,
    });
    return {
      metrics,
      payload: {
        defId: payload ? String(payload.id || "") : null,
        path: payload ? String(payload.source || "payload") : "none",
        hooks: hookOut,
        script: scriptOut,
        hookResult,
        throw: throwSpec,
      },
    };
  }

  if (hookResult.consumed) {
    // Emit throw arc directly (bypass event buffer) so throwFxController
    // receives it BEFORE tx.commit() destroys the entity.
    ctx.world.emit?.("item:thrown", {
      actor, itemId, targetId,
      from: { ...throwSpec.from },
      to: { ...throwSpec.to },
      range: throwSpec.range,
      maxRange: throwSpec.maxRange,
      weight: throwSpec.weight,
      weaponFamily: String(info?.weaponFamily || ""),
      path: metrics.path,
      consumed: true,
    });
    ctx.mutate.consume(itemId, actor);
    metrics.consumed = true;
  } else if (!hookResult.skipBaseThrow) {
    const landing = normalizePoint(hookResult.at, throwSpec.to);
    let impact = null;

    if (canDealThrowImpactDamage(info, identity)) {
      const defender = resolveThrowImpactTarget(ctx, actor, targetId, landing);
      if (defender > 0) {
        const af = ctx.query.get(actor, Faction)?.key || "";
        const df = ctx.query.get(defender, Faction)?.key || "";
        if (areFactionsHostile(af, df)) {
          const damage = rollThrowImpactDamage(ctx, info || {}, actor);
          const projectileDelay = computeProjectileDelay(throwSpec.from, landing, 26, 0.09, 0.32);
          ctx.mutate.queue({
            type: "damage",
            entityId: defender,
            amount: damage,
            source: actor,
            damageType: "physical",
            projectileDelay,
          });
          metrics.impacted = true;
          metrics.impactDamage = damage;
          impact = { targetId: defender, damage };
          ctx.io.emit("item:throw-impact", {
            actor,
            itemId,
            targetId: defender,
            at: { ...landing },
            damage,
          });
        }
      }
    }

    const throwInfo = ctx.query.itemInfo(itemId);
    const stackCount = Math.max(1, Number(throwInfo?.count || 1) | 0);

    if (stackCount > 1) {
      // Decrement the stack in inventory; spawn a single copy at landing.
      ctx.mutate.patchItemInfo(itemId, { count: stackCount - 1 });
      const identity = ctx.query.identity(itemId);
      ctx.mutate.spawnItem(identity, landing.x, landing.y, { count: 1 });
    } else {
      ctx.mutate.queue({
        type: "dropFromInventory",
        entityId: itemId,
        inventoryOwnerId: actor,
        x: landing.x,
        y: landing.y,
        emitEvent: false,
      });
    }
    metrics.dropped = true;
    ctx.io.emit("item:thrown", {
      actor,
      itemId,
      targetId,
      from: { ...throwSpec.from },
      to: { ...landing },
      range: throwSpec.range,
      maxRange: throwSpec.maxRange,
      weight: throwSpec.weight,
      weaponFamily: String(info?.weaponFamily || ""),
      path: metrics.path,
      impact,
    });
  }

  return {
    metrics,
    payload: {
      defId: payload ? String(payload.id || "") : null,
      path: payload ? String(payload.source || "payload") : "none",
      hooks: hookOut,
      script: scriptOut,

  if (targetPoint) {
    const dist = chebyshevScalar(from.x | 0, from.y | 0, targetPoint.x | 0, targetPoint.y | 0);
    if (dist > 0) {
      const cappedRange = Math.min(maxRange, dist);
      const projected = projectTowardTarget(
        from.x | 0,
        from.y | 0,
        targetPoint.x | 0,
        targetPoint.y | 0,
        cappedRange,
      );
      const stepX = (projected.x | 0) - (from.x | 0);
      const stepY = (projected.y | 0) - (from.y | 0);
      dx = Math.sign(stepX);
      dy = Math.sign(stepY);
      range = Math.max(1, chebyshevScalar(0, 0, stepX, stepY));
      to = { x: projected.x | 0, y: projected.y | 0 };
    }
  }

  return {
    from: { x: from.x | 0, y: from.y | 0 },
    to,
    dx,
    dy,
    range,
    maxRange,
    weight: normalizedWeight,
    target: targetPoint ? { x: targetPoint.x | 0, y: targetPoint.y | 0 } : null,
  };
}

/**
 * throwSystem — resolves ThrowIntent through Action Runtime + throw pipeline.
 * @param {World} world
 */
export function throwSystem(world) {
  for (const [actor, intent] of world.query(ThrowIntent)) {
    const itemId = intent.itemId | 0;
    const targetId = intent.targetId | 0;
    const throwSpec = resolveThrowSpec(world, actor, itemId, intent);
    let result = null;

    try {
      result = executeInteraction(world, {
        verb: "throw",
        actor,
        primary: itemId,
        target: targetId,
        params: { intent, throwSpec },
        pipeline: throwPipeline,
      });
    } catch (error) {
      result = {
        schemaVersion: 1,
        kind: "interaction",
        verb: "throw",
        actor,
        primary: itemId,
        target: targetId,
        ok: false,
        canceled: true,
        reason: "RUNTIME_ERROR",
        detail: { message: String(error?.message || error || "unknown runtime error") },
        metrics: { committedOps: 0, emittedEvents: 0 },
        payload: null,
        breadcrumbs: [],
        warnings: [{ code: "runtime:error", detail: { message: String(error?.message || error || "") } }],
      };
    }

    if (result?.canceled && typeof result.reason === "string" && !result.reason.startsWith("THROW_GATE_")) {
      const detail = result?.detail && typeof result.detail === "object" ? result.detail : {};
      world.emit("item:throw-cancelled", {
        actor,
        itemId,
        targetId,
        code: detail?.code || result.reason,
        message: detail?.message,
        consumesTurn: detail?.consumesTurn,
      });
    }

    world.emit("interaction:result", result);
    try { world.remove(actor, ThrowIntent); } catch {} // ECS: may not exist
  }
}
    });

    return { consumed: true, at, element, charges };
  };
}

// ── Potion Splash on Throw ─────────────────────────────────────────────
// Generic factory for potions that splash their effect onto whatever is
// standing on the landing tile when thrown.

/**
 * @param {{
 *   effectKey?: string,
 *   duration?: number,
 *   potency?: number,
 *   damage?: number,
 *   damageType?: string,
 *   healPct?: number,
 *   hazardKind?: string|null,
 *   hazardTurns?: number,
 *   hazardTickDamage?: number,
 *   sourceKind?: string,
 *   eventName?: string,
 * }} [opts]
 */
export function createPotionSplashThrowHook(opts = {}) {
  const effectKey = String(opts?.effectKey || "");
  const duration = Math.max(0, Number(opts?.duration || 10) | 0);
  const potency = Number(opts?.potency ?? 1);
  const damage = Math.max(0, Number(opts?.damage || 0) | 0);
  const damageType = String(opts?.damageType || "physical");
  const healPct = Number(opts?.healPct || 0);
  const hazardKind = opts?.hazardKind || null;
  const hazardTurns = Math.max(1, Number(opts?.hazardTurns ?? 2) | 0);
  const hazardTickDmg = Math.max(0, Number(opts?.hazardTickDamage ?? 0) | 0);
  const sourceKind = String(opts?.sourceKind || "thrown_potion");
  const eventName = String(opts?.eventName || "potion:splash");

  return (ctx, state) => {
    const actorId = Number(state?.actor || ctx.actor || 0) | 0;
    const itemId = Number(state?.itemId || ctx.primary || 0) | 0;
    const throwSpec = (state?.throw && typeof state.throw === "object") ? state.throw : null;
    const fallback = ctx.helpers.adjacentPoint(actorId);
    const at = {
      x: Number.isFinite(Number(throwSpec?.to?.x)) ? (Number(throwSpec.to.x) | 0) : (fallback.x | 0),
      y: Number.isFinite(Number(throwSpec?.to?.y)) ? (Number(throwSpec.to.y) | 0) : (fallback.y | 0),
    };

    const hitIds = ctx.query.livingAt(at.x, at.y, {});
    for (const hitId of (Array.isArray(hitIds) ? hitIds : [])) {
      if (damage > 0) {
        ctx.mutate.queue({
          type: "damage",
          entityId: hitId,
          amount: damage,
          source: actorId,
          damageType,
        });
      }
      if (healPct > 0) {
        const vit = ctx.query.get(hitId, Vitality);
        if (vit) {
          const amount = Math.max(1, Math.floor((vit.maxHp | 0) * healPct));
          ctx.mutate.heal(hitId, amount);
        }
      }
      if (effectKey) {
        ctx.helpers.addEffect(hitId, {
          key: effectKey,
          potency,
          turnsLeft: duration,
          onsetLeft: 0,
          peakLeft: 0,
          stack: "refresh",
          maxStacks: 1,
          sourceId: itemId,
          meta: { source: sourceKind, delivery: "splash" },
        });
      }
    }

    if (hazardKind) {
      ctx.helpers.hazardSpawn({
        kind: hazardKind,
        medium: "floor",
        turnsLeft: hazardTurns,
        radius: 0,
        tickDamage: hazardTickDmg,
        damageType,
        cause: "potion_splash",
        sourceId: actorId,
        sourceKind,
        meta: { source: sourceKind, delivery: "thrown" },
      }, at);
    }

    ctx.io.emit(eventName, {
      actor: actorId,
      itemId,
      at: { ...at },
      effectKey: effectKey || null,
      hitCount: Array.isArray(hitIds) ? hitIds.length : 0,
    });

    return { consumed: true, at, effectKey: effectKey || null };
  };
}

